// Разбор ответа OpenSearch (единый индекс): договоры + пункты из inner_hits
const b = $('Build request').first().json;
const r = $input.first().json;

if (r.error) {
  const e = r.error;
  const msg = typeof e === 'string' ? e : [e.message, e.description].filter(Boolean).join(': ') || JSON.stringify(e);
  throw new Error('OpenSearch: ' + String(msg).slice(0, 700));
}

const hits = (r.hits && r.hits.hits) || [];
const total = r.hits && r.hits.total ? (r.hits.total.value ?? r.hits.total) : hits.length;

// значение по пути 'counterparty.name'
const at = (o, path) => {
  if (o == null) return undefined;
  if (path in o) return o[path];
  return path.split('.').reduce((a, key) => (a == null ? undefined : a[key]), o);
};
const day = v => (v ? String(v).slice(0, 10) : undefined);
const contractView = s => ({
  ref: at(s, 'barcode') == null ? undefined : String(at(s, 'barcode')),
  contract_ref: at(s, 'contract_ref') || undefined,   // ссылка 1С: из неё «Ответ для формы» строит навигационную ссылку   // штрихкод: по нему форма открывает текст, по нему же проверяются права
  number: at(s, 'registration_number'),
  date: day(at(s, 'registration_date')),
  title: at(s, 'title'),
  document_type: at(s, 'document_type.name'),
  contract_type: at(s, 'contract_type.name'),
  counterparty: at(s, 'counterparty.name'),
  counterparty_inn: at(s, 'counterparty.inn'),
  organization: at(s, 'organization.name'),
  sum: at(s, 'sum') ?? undefined,
  currency: at(s, 'currency') || undefined,
  valid_from: day(at(s, 'valid_from')),
  valid_to: day(at(s, 'valid_to')),
  is_amendment: at(s, 'contract_parent_ref') && at(s, 'contract_parent_ref') !== at(s, 'contract_ref') ? true : undefined
});

// ---------- scope=text: полный текст договора ----------
if (b.scope === 'text') {
  if (!hits.length) return [{ json: { ok: false, error: 'Договор с таким штрихкодом не найден в индексе' } }];
  const s0 = hits[0]._source || {};
  const chunks = (Array.isArray(s0.chunks) ? s0.chunks : [])
    .map(c => ({ i: Number(c.chunk_index), t: c.chunk_type, text: String(c.chunk_text || '') }))
    .sort((x, y) => x.i - y.i);
  return [{ json: { ok: true, scope: 'text', ref: b.ref, contract_ref: at(s0, 'contract_ref') || undefined,
    header: { number: at(s0, 'registration_number'), date: day(at(s0, 'registration_date')), title: at(s0, 'title'), document_type: at(s0, 'document_type.name'),
              counterparty: at(s0, 'counterparty.name'), valid_from: day(at(s0, 'valid_from')), valid_to: day(at(s0, 'valid_to')),
              sum: at(s0, 'sum') ?? undefined, currency: at(s0, 'currency') || undefined },
    full_text: String(s0.full_text || ''),
    chunks } }];
}

// ---------- scope=count ----------
if (b.scope === 'count' && b.rights) {
  // права проверяются по списку договоров: берём ссылки, число пересчитает «Применить права»
  return [{ json: { ok: true, applied: b.applied, scope: 'count', raw_total: total ?? null, contracts: hits.map(h => contractView(h._source || {})).filter(c => c.ref) } }];
}
if (b.scope === 'count') {
  return [{ json: { ok: true, applied: b.applied, scope: 'count', total: total ?? null } }];
}

// ---------- scope=contracts ----------
if (b.scope === 'contracts') {
  const contracts = hits.map(h => contractView(h._source || {})).filter(c => c.ref);
  return [{ json: { ok: true, applied: b.applied, scope: 'contracts', total, contracts,
                    hint: contracts.length ? undefined : 'Договоры не найдены' } }];
}

// ---------- scope=chunks: договоры в порядке гибридного ранжирования, пункты из inner_hits ----------
const MAXLEN = 1500;
const innerOf = (h, name) => ((h.inner_hits && h.inner_hits[name] && h.inner_hits[name].hits && h.inner_hits[name].hits.hits) || [])
  .map(ih => ih._source || {});

const contracts = [];
let fragments_found = 0;
let no_barcode = 0;
for (const h of hits.slice(0, b.rights ? b.k_fetch : b.k)) {
  const sem = innerOf(h, 'sem'), lex = innerOf(h, 'lex');
  // чередуем: лучший смысловой, лучший по словам, второй смысловой ... без повторов
  const picked = new Map();
  for (let i = 0; i < Math.max(sem.length, lex.length) && picked.size < b.frags_per_contract; i++) {
    for (const c of [sem[i], lex[i]]) {
      if (!c || picked.size >= b.frags_per_contract) continue;
      const key = c.chunk_id ?? c.chunk_index;
      if (!picked.has(key)) picked.set(key, c);
    }
  }
  const fragments = [...picked.values()]
    .map(c => ({ chunk_index: c.chunk_index, chunk_type: c.chunk_type, text: String(c.chunk_text || '').slice(0, MAXLEN) }))
    .sort((x, y) => (x.chunk_index ?? 0) - (y.chunk_index ?? 0));
  if (!fragments.length) continue;
  const view = contractView(h._source || {});
  if (!view.ref) { no_barcode++; continue; }   // без штрихкода договор нельзя ни открыть, ни проверить по правам
  fragments_found += fragments.length;
  contracts.push({ ...view, fragments });
}

return [{ json: {
  ok: true, applied: b.applied, scope: 'chunks', fragments_found, contracts,
  debug: { hits: hits.length, total, filtered: b.filtered, no_barcode },
  hint: contracts.length ? undefined :
    (b.filtered ? 'Ничего не найдено в рамках заданного отбора (организации, контрагенты, даты, ИНН, номер, сумма). Возможно, отбор слишком узкий; сообщи об этом пользователю или переформулируй запрос' : 'Ничего не найдено: попробуйте другие формулировки')
} }];

// Готовим запрос в 1С (HTTP-сервис RPA): Method + Elements[ { ДоменноеИмяПользователя, МассивСтрокGUID } ] - в массиве штрихкоды договоров
const b = $('Build request').first().json;
const r = $('Parse result').first().json;
if (r.ok === false) return [{ json: { skip: true, ok: true, ids: [] } }]; // договор не найден - проверять нечего
const account = String($('When called by agent').first().json.user_account || '').trim();

let ids = [];
if (b.rights) ids = b.scope === 'text' ? [b.ref] : (r.contracts || []).map(c => c.ref);
ids = [...new Set(ids.map(x => String(x || '').trim()).filter(Boolean))].slice(0, 200);

if (!ids.length) return [{ json: { skip: true, ok: true, ids } }];
if (!account) return [{ json: { skip: true, ok: false, error: 'не передана учётная запись пользователя', ids } }];

const S = b.soap;
const payload = {
  Method: S.method,
  Elements: [ { 'ДоменноеИмяПользователя': account, 'МассивСтрокGUID': ids } ]
};
return [{ json: { skip: false, url: S.url, payload, ids } }];

// Вызов HTTP-сервиса 1С с проверкой доступности: любая сетевая ошибка превращается в понятный текст
const q = $('Запрос прав').first().json;
if (q.skip) return [{ json: { skipped: true } }];
const S = $('Build request').first().json.soap;

const opts = {
  method: 'POST', url: q.url,
  headers: { 'Content-Type': 'application/json; charset=utf-8', 'Accept': 'application/json' },
  body: JSON.stringify(q.payload),
  returnFullResponse: true, ignoreHttpStatusErrors: true, json: false,
  timeout: S.timeout || 15000
};
if (S.login) opts.auth = { username: S.login, password: S.password };

const HINTS = {
  EAI_AGAIN: 'не удалось разрешить имя хоста (DNS); используйте IP или extra_hosts/dns в docker',
  ENOTFOUND: 'имя хоста не найдено (DNS)',
  ECONNREFUSED: 'соединение отклонено: веб-сервер 1С не слушает этот адрес/порт',
  ETIMEDOUT: 'таймаут соединения: нет сетевого маршрута или блокирует файрвол/прокси (проверьте NO_PROXY)',
  ECONNABORTED: 'таймаут ответа: 1С не ответила за ' + ((S.timeout || 15000) / 1000) + ' с',
  EHOSTUNREACH: 'хост недоступен: нет маршрута до сервера 1С',
  ENETUNREACH: 'сеть недоступна: нет маршрута до сервера 1С',
  ECONNRESET: 'соединение сброшено сервером 1С или прокси'
};
try {
  const r = await this.helpers.httpRequest(opts);
  const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body);
  return [{ json: { statusCode: Number(r.statusCode), body } }];
} catch (e) {
  const code = e.code || (e.cause && e.cause.code) || '';
  const msg = String(e.message || e).split('\n')[0].slice(0, 200);
  const hint = HINTS[code] || (/circular|EnvProxy/i.test(msg) ? 'соединение не установлено (проверьте сеть до сервера 1С и NO_PROXY)' : '');
  return [{ json: { error: 'недоступен сервис 1С ' + q.url + (code ? ' [' + code + ']' : '') + (hint ? ': ' + hint : ': ' + msg) } }];
}

// Оставляем только то, на что у пользователя есть права по ответу 1С. Нет ответа 1С - ничего не отдаём.
const b = $('Build request').first().json;
const r = $('Parse result').first().json;
if (!b.rights || r.ok === false) return [{ json: r }];

const q = $('Запрос прав').first().json;
const fail = msg => [{ json: { ok: false, error: 'Не удалось проверить права доступа: ' + msg,
  hint: 'Сообщи пользователю, что проверка прав сейчас недоступна и результаты показать нельзя; повторять поиск не нужно' } }];

let allowed = new Set();
if (q.skip) {
  if (q.ok === false) return fail(q.error);
} else {
  let h;
  try { h = $('1C Права').first().json; } catch (e) { return fail('нет ответа от 1С'); }
  if (h.error) return fail(String(h.error.message || h.error).slice(0, 400));
  const body = String(h.body ?? h.data ?? '');
  const status = Number(h.statusCode || 200);
  if (status >= 400) {
    const why = status === 401 || status === 403 ? 'нет доступа к сервису (проверьте логин/пароль 1С)' : status === 404 ? 'метод или адрес HTTP-сервиса не найден' : status === 405 ? 'сервис не принимает POST' : '';
    return fail('1С вернула ошибку ' + status + (why ? ' - ' + why : '') + ': ' + body.replace(/\s+/g, ' ').trim().slice(0, 300));
  }
  // формат ответа не важен (JSON/XML/текст): разбиваем ответ на «слова» и оставляем из запрошенных штрихкодов те, что 1С вернула.
  // Сравнение точное по целому значению, поэтому штрихкод 123 не совпадёт с 1234.
  const tokens = new Set((body.match(/[0-9A-Za-zА-Яа-яЁё_\-\/.]+/g) || []).map(x => x.toLowerCase()));
  allowed = new Set(q.ids.map(x => String(x).toLowerCase()).filter(x => tokens.has(x)));
}
const ok = c => c.ref && allowed.has(String(c.ref).toLowerCase());
const NONE = 'Среди доступных вам договоров ничего не найдено';

if (r.scope === 'text') {
  return allowed.has(String(r.ref).toLowerCase()) ? [{ json: r }] : [{ json: { ok: false, error: 'Нет доступа к этому договору' } }];
}
const all = r.contracts || [];
const mine = all.filter(ok);

if (r.scope === 'count') {
  const capped = r.raw_total != null && r.raw_total > all.length;
  return [{ json: { ok: true, applied: r.applied, scope: 'count', total: mine.length,
    hint: capped ? 'Подсчёт неполный: проверены первые ' + all.length + ' договоров из ' + r.raw_total + '; предложи сузить отбор' : undefined } }];
}
if (r.scope === 'contracts') {
  const list = mine.slice(0, b.k);
  return [{ json: { ok: true, applied: r.applied, scope: 'contracts', total: mine.length, contracts: list, hint: list.length ? undefined : (all.length ? NONE : r.hint) } }];
}
let left = b.k;                       // chunks: не больше k фрагментов
const contracts = [];
for (const c of mine) {
  if (left <= 0) break;
  const fr = (c.fragments || []).slice(0, left);
  left -= fr.length;
  if (fr.length) contracts.push({ ...c, fragments: fr });
}
return [{ json: { ok: true, applied: r.applied, scope: 'chunks', debug: r.debug, fragments_found: b.k - left, contracts, hint: contracts.length ? undefined : (all.length ? NONE : r.hint) } }];

// ===== НАСТРОЙКИ =====
const CFG = {
  os_url: 'https://192.168.210.233:9200',
  index: 'contracts_with_chunks',   // единый индекс (алиас): реквизиты + full_text + nested chunks
  pipeline: 'contracts-hybrid',     // search pipeline для hybrid (normalization-processor)
  use_hybrid: true,                 // false — bool/should вместо hybrid (если pipeline не создан)
  expand_nested: false,             // true — от семантики несколько пунктов на договор (expand_nested_docs)
  sum_numeric: true,                // sum в индексе числовой (scaled_float); false — отбор по сумме не применяется
  default_k: 8,
  max_k: 15,
  frags_per_contract: 3,            // сколько пунктов брать с одного договора
  rights_enforce: true,   // true - результаты проверяются в 1С по правам пользователя; false - отключить (только для отладки)
  rights_overfetch: 3,    // во сколько раз больше берём из индекса, т.к. часть договоров отсеется по правам
  count_cap: 500,         // сколько договоров максимум проверяем при подсчёте (scope=count)
  // ---- проверка прав в 1С (HTTP-сервис) ----
  rights_url: 'http://192.168.100.149/DOC/hs/RPA',
  rights_method: 'AvailableUserDocuments',     // постоянное значение поля Method в теле запроса
  rights_login: '',                            // Basic-авторизация к HTTP-сервису 1С; пусто - без авторизации
  rights_password: '',
  rights_timeout_ms: 15000,
};
const SOAP = { url: CFG.rights_url, method: CFG.rights_method, login: CFG.rights_login, password: CFG.rights_password, timeout: CFG.rights_timeout_ms };

// реквизиты договора из _source (без full_text и без chunks с эмбеддингами)
// barcode - ключ договора везде: ссылки формы, текст договора, проверка прав в 1С
const REQUISITES = [
  'barcode', 'contract_ref', 'contract_parent_ref', 'registration_number', 'registration_date', 'title',
  'document_type.name', 'contract_type.name', 'counterparty.name', 'counterparty.inn',
  'organization.name', 'organization.inn', 'valid_from', 'valid_to', 'sum', 'currency'
];
// поля пунктов (chunk_text_semantic_info с эмбеддингом не берём)
const CHUNK_SRC = ['chunks.chunk_id', 'chunks.chunk_index', 'chunks.chunk_type', 'chunks.chunk_text'];
// ======================

const inp = $input.first().json;
const q = String(inp.query || '').trim();
let scope = ['contracts', 'count', 'text'].includes(inp.scope) ? inp.scope : 'chunks';
const k = Math.min(Number(inp.top_k) || CFG.default_k, CFG.max_k);
const RIGHTS = !!CFG.rights_enforce;
const kFetch = RIGHTS ? Math.min(k * CFG.rights_overfetch, 60) : k;
const minSum = Number(inp.min_sum) > 0 ? Number(inp.min_sum) : 0;
const maxSum = Number(inp.max_sum) > 0 ? Number(inp.max_sum) : 0;

// предварительный отбор из формы (организации и контрагенты по ИНН+КПП, дата договора)
let ff = {};
if (inp.filters_json && typeof inp.filters_json === 'object') ff = inp.filters_json;
else { try { ff = inp.filters_json ? JSON.parse(inp.filters_json) : {}; } catch (e) { throw new Error('filters_json не разобран: ' + String(inp.filters_json).slice(0, 200)); } }
if (!ff || typeof ff !== 'object') ff = {};
const ffOrgs = Array.isArray(ff.organizations) ? ff.organizations : [];
const ffCps = Array.isArray(ff.counterparties) ? ff.counterparties : [];
const hasFormFilters = ffOrgs.length > 0 || ffCps.length > 0 || !!ff.date_from || !!ff.date_to;

if (scope !== 'text' && !q && !inp.contract_number && !inp.counterparty_inn && !inp.organization_inn && !hasFormFilters && !minSum && !maxSum) {
  throw new Error('Пустой запрос: нужен query, contract_number, counterparty_inn или отбор');
}

// фильтры по реквизитам договора (поля верхнего уровня)
const filter = [];
if (inp.organization_inn) filter.push({ term: { 'organization.inn': String(inp.organization_inn) } });
if (inp.counterparty_inn) filter.push({ term: { 'counterparty.inn': String(inp.counterparty_inn) } });
if (inp.contract_number) {
  const num = String(inp.contract_number).trim();
  filter.push({ bool: { minimum_should_match: 1, should: [
    { term: { registration_number: num } },
    { match_phrase: { 'registration_number.text': num } }
  ] } });
}
if (CFG.sum_numeric && (minSum || maxSum)) {
  const r = {};
  if (minSum) r.gte = minSum;
  if (maxSum) r.lte = maxSum;
  filter.push({ range: { sum: r } });
}

// ---- отбор формы: накладывается кодом, как граница поиска (AND с остальными условиями) ----
const reqKeys = (path, o) => {
  const must = [{ term: { [path + '.inn']: String(o.inn) } }];
  if (o.kpp) must.push({ term: { [path + '.kpp']: String(o.kpp) } });   // у ИП/физлиц КПП нет - тогда по одному ИНН
  return { bool: { filter: must } };
};
const pairsClause = (path, arr) => {
  const ok = arr.filter(o => o && /^\d{10}$|^\d{12}$/.test(String(o.inn || '')));
  return ok.length ? { bool: { should: ok.map(o => reqKeys(path, o)), minimum_should_match: 1 } } : null;
};
const orgClause = pairsClause('organization', ffOrgs);
if (orgClause) filter.push(orgClause);
const cpClause = pairsClause('counterparty', ffCps);
if (cpClause) filter.push(cpClause);
const validN = arr => arr.filter(o => o && /^\d{10}$|^\d{12}$/.test(String(o.inn || ''))).length;
const isIso = s => /^\d{4}-\d{2}-\d{2}$/.test(String(s || ''));
if (isIso(ff.date_from) || isIso(ff.date_to)) {
  const r = { format: 'yyyy-MM-dd' };
  if (isIso(ff.date_from)) r.gte = ff.date_from + '||/d';   // граница включается
  if (isIso(ff.date_to)) r.lte = ff.date_to + '||/d';       // до конца указанного дня включительно
  filter.push({ range: { registration_date: r } });
}
const applied = { organizations: validN(ffOrgs), counterparties: validN(ffCps), date_from: isIso(ff.date_from) ? ff.date_from : null, date_to: isIso(ff.date_to) ? ff.date_to : null };

const base = `${CFG.os_url}/${CFG.index}/_search`;
const result = (scopeOut, body, hybrid, extra = {}) => [{ json: {
  url: hybrid ? `${base}?search_pipeline=${CFG.pipeline}` : base,
  body, scope: scopeOut, k, k_fetch: kFetch, rights: RIGHTS, applied, soap: SOAP,
  filtered: filter.length > 0, frags_per_contract: CFG.frags_per_contract, ...extra
} }];

// scope=text: полный текст одного договора (отбор формы не применяется, права проверяются дальше)
if (scope === 'text') {
  const ref = String(inp.ref || '').trim();   // штрихкод договора
  if (!ref || ref.length > 120) throw new Error('Не передан штрихкод договора');
  return result('text', {
    size: 1,
    _source: { includes: [...REQUISITES, 'full_text', ...CHUNK_SRC] },
    query: { term: { barcode: ref } }
  }, false, { ref });
}

// без текста запроса пункты искать нечем - отдаём договоры по реквизитам
if (scope === 'chunks' && !q) scope = 'contracts';

if (scope === 'contracts' || scope === 'count') {
  const body = {
    size: scope === 'count' ? (RIGHTS ? CFG.count_cap : 0) : kFetch,
    track_total_hits: true,
    _source: { includes: REQUISITES },
    query: { bool: { filter } }
  };
  if (q) body.query.bool.must = [{ multi_match: { query: q, fields: ['registration_number.text^3', 'title^2', 'counterparty.name^2', 'full_text'] } }];
  else body.sort = [{ registration_date: { order: 'desc', missing: '_last' } }];
  return result(scope, body, false);
}

// scope=chunks: гибрид BM25 по пунктам + семантика по пунктам, пункты приходят в inner_hits
const F = CFG.frags_per_contract;
const innerHits = name => ({ name, size: F, _source: { includes: CHUNK_SRC } });

const lexical = { bool: {
  must: [{ nested: { path: 'chunks', score_mode: 'max',
    query: { match: { 'chunks.chunk_text': q } },
    inner_hits: innerHits('lex') } }],
  filter
} };

// фильтры кладём и ВНУТРЬ neural-запроса, иначе они режут уже найденных соседей
const neural = { query_text: q, k: Math.max(kFetch * 3, 50) };
if (filter.length) neural.filter = { bool: { filter } };
if (CFG.expand_nested) neural.expand_nested_docs = true;
const semantic = { bool: {
  must: [{ nested: { path: 'chunks', score_mode: 'max',
    query: { neural: { 'chunks.chunk_text': neural } },
    inner_hits: innerHits('sem') } }],
  filter
} };

return result('chunks', {
  size: kFetch,
  _source: { includes: REQUISITES },
  query: CFG.use_hybrid
    ? { hybrid: { queries: [lexical, semantic] } }
    : { bool: { should: [lexical, semantic], minimum_should_match: 1 } }
}, CFG.use_hybrid);
